(function (){'use strict';function getFileExtension(filename){return filename.split('.').pop().toLowerCase();}function formatBytes(bytes,decimals=2){if (!bytes||bytes===0)return '0 Bytes';const k=1024;const dm=decimals<0?0:decimals;const sizes=['Bytes','KB','MB','GB'];const i=Math.floor(Math.log(bytes)/Math.log(k));return parseFloat((bytes/Math.pow(k,i)).toFixed(dm))+' '+sizes[i];}const ICONS={pdf:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="9" y1="15" x2="12" y2="15"></line><line x1="9" y1="18" x2="15" y2="18"></line><line x1="9" y1="12" x2="10" y2="12"></line></svg>`,image:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><circle cx="8.5" cy="8.5" r="1.5"></circle><polyline points="21 15 16 10 5 21"></polyline></svg>`,word:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><line x1="16" y1="13" x2="8" y2="13"></line><line x1="16" y1="17" x2="8" y2="17"></line><polyline points="10 9 9 9 8 9"></polyline></svg>`,excel:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><line x1="9" y1="3" x2="9" y2="21"></line><line x1="15" y1="3" x2="15" y2="21"></line><line x1="3" y1="9" x2="21" y2="9"></line><line x1="3" y1="15" x2="21" y2="15"></line></svg>`,zip:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline><circle cx="12" cy="18" r="2"></circle><line x1="12" y1="8" x2="12" y2="16"></line></svg>`,generic:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"></path><polyline points="14 2 14 8 20 8"></polyline></svg>`};function getIconForExtension(ext){if (['jpg','jpeg','png','webp','gif','svg'].includes(ext))return ICONS.image;if (ext==='pdf')return ICONS.pdf;if (['doc','docx','rtf'].includes(ext))return ICONS.word;if (['xls','xlsx','csv'].includes(ext))return ICONS.excel;if (['zip','rar','7z','tar','gz'].includes(ext))return ICONS.zip;return ICONS.generic;}class UniversityAttachmentsManager{constructor(){this.formsetPrefix='attachments';this.container=document.getElementById('attachment-formset-container');if (!this.container)return;this.dropzoneText=this.container.getAttribute('data-dropzone-text')||'اسحب الملفات هنا أو انقر لاختيارها';this.emptyText=this.container.getAttribute('data-empty-text')||'لا توجد ملفات مرفوعة حالياً. يمكنك رفع أول ملف باستخدام مساحة السحب أدناه.';this.managementForm=document.getElementById(`id_${this.formsetPrefix}-TOTAL_FORMS`);this.minFormInput=document.getElementById(`id_${this.formsetPrefix}-MIN_NUM_FORMS`);this.maxFormInput=document.getElementById(`id_${this.formsetPrefix}-MAX_NUM_FORMS`);this.init();}init(){this.wrapper=document.createElement('div');this.wrapper.className='attachments-manager';this.listContainer=document.createElement('div');this.listContainer.className='attachments-list';this.dropzone=this.createDropzone();this.wrapper.appendChild(this.listContainer);this.wrapper.appendChild(this.dropzone);this.formsData=[];const originalForms=Array.from(this.container.querySelectorAll(':scope>div'));originalForms.forEach((formEl,index)=>{const titleInput=formEl.querySelector(`[name="${this.formsetPrefix}-${index}-title"]`);const fileInput=formEl.querySelector(`[name="${this.formsetPrefix}-${index}-file"]`);const deleteInput=formEl.querySelector(`[name="${this.formsetPrefix}-${index}-DELETE"]`);const idInput=formEl.querySelector(`[name="${this.formsetPrefix}-${index}-id"]`);let existingFileUrl=null;let existingFileSize=0;const fileLink=formEl.querySelector('a');if (fileLink){existingFileUrl=fileLink.getAttribute('href');const sizeMatch=formEl.textContent.match(/\(([^)]+)\)/);if (sizeMatch&&sizeMatch[1]){existingFileSize=sizeMatch[1];}}this.formsData.push({el:formEl,index:index,titleInput:titleInput,fileInput:fileInput,deleteInput:deleteInput,idInput:idInput,existingUrl:existingFileUrl,existingSize:existingFileSize,isNew:false});formEl.style.display='none';});this.container.appendChild(this.wrapper);this.render();this.setupDropzoneEvents();}createDropzone(){const dropzone=document.createElement('div');dropzone.className='attachment-dropzone';dropzone.innerHTML=`<div class="attachment-dropzone-icon"><svg style="width:40px;height:40px;" fill="none" stroke="currentColor" stroke-width="1.5" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M12 16.5V9.75m0 0l3 3m-3-3l-3 3M6.75 19.5a4.5 4.5 0 01-1.41-8.775 5.25 5.25 0 0110.233-2.33 3 3 0 013.758 3.848A3.752 3.752 0 0118 19.5H6.75z"></path></svg></div><div class="attachment-dropzone-text">${this.dropzoneText}</div><div class="attachment-dropzone-help">يمكنك رفع ملفات PDF، Word أو صور بمساحة قصوى 10MB للملف</div><input type="file" multiple id="attachment-dropzone-file-input" style="display:none;" accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,.zip,.rar">`;return dropzone;}setupDropzoneEvents(){const fileInput=this.dropzone.querySelector('#attachment-dropzone-file-input');this.dropzone.addEventListener('click',(e)=>{if (e.target!==fileInput){fileInput.click();}});fileInput.addEventListener('change',()=>{if (fileInput.files.length>0){this.handleNewFiles(fileInput.files);fileInput.value='';}});this.dropzone.addEventListener('dragover',(e)=>{e.preventDefault();e.stopPropagation();this.dropzone.classList.add('dragover');});this.dropzone.addEventListener('dragleave',(e)=>{e.preventDefault();e.stopPropagation();this.dropzone.classList.remove('dragover');});this.dropzone.addEventListener('drop',(e)=>{e.preventDefault();e.stopPropagation();this.dropzone.classList.remove('dragover');const files=e.dataTransfer.files;if (files.length>0){this.handleNewFiles(files);}});}handleNewFiles(files){Array.from(files).forEach(file=>{let targetForm=this.formsData.find(form=>!form.existingUrl&&(!form.fileInput.files||form.fileInput.files.length===0)&&!form.isNew);if (!targetForm){targetForm=this.cloneFormsetRow();}const dataTransfer=new DataTransfer();dataTransfer.items.add(file);targetForm.fileInput.files=dataTransfer.files;const defaultTitle=file.name.substring(0,file.name.lastIndexOf('.'))||file.name;targetForm.titleInput.value=defaultTitle;targetForm.isNew=true;targetForm.newFileName=file.name;targetForm.newFileSize=formatBytes(file.size);});this.render();}cloneFormsetRow(){const lastForm=this.formsData[this.formsData.length-1];if (!lastForm)return null;const clonedEl=lastForm.el.cloneNode(true);const nextIndex=this.formsData.length;clonedEl.querySelectorAll('[name],[id],[for]').forEach(element=>{const name=element.getAttribute('name');if (name){element.setAttribute('name',name.replace(new RegExp(`${this.formsetPrefix}-\\d+-`),`${this.formsetPrefix}-${nextIndex}-`));}const id=element.getAttribute('id');if (id){element.setAttribute('id',id.replace(new RegExp(`id_${this.formsetPrefix}-\\d+-`),`id_${this.formsetPrefix}-${nextIndex}-`));}const forAttr=element.getAttribute('for');if (forAttr){element.setAttribute('for',forAttr.replace(new RegExp(`id_${this.formsetPrefix}-\\d+-`),`id_${this.formsetPrefix}-${nextIndex}-`));}});const titleInput=clonedEl.querySelector(`[name="${this.formsetPrefix}-${nextIndex}-title"]`);const fileInput=clonedEl.querySelector(`[name="${this.formsetPrefix}-${nextIndex}-file"]`);const deleteInput=clonedEl.querySelector(`[name="${this.formsetPrefix}-${nextIndex}-DELETE"]`);const idInput=clonedEl.querySelector(`[name="${this.formsetPrefix}-${nextIndex}-id"]`);if (titleInput)titleInput.value='';if (fileInput)fileInput.value='';if (deleteInput)deleteInput.checked=false;if (idInput)idInput.value='';const existingLinks=clonedEl.querySelectorAll('p,a');existingLinks.forEach(link=>link.remove());clonedEl.style.display='none';this.container.appendChild(clonedEl);this.managementForm.value=nextIndex+1;const newForm={el:clonedEl,index:nextIndex,titleInput:titleInput,fileInput:fileInput,deleteInput:deleteInput,idInput:idInput,existingUrl:null,existingSize:0,isNew:true};this.formsData.push(newForm);return newForm;}toggleDelete(index){const formData=this.formsData[index];if (!formData)return;if (formData.isNew&&!formData.existingUrl){formData.fileInput.value='';formData.titleInput.value='';formData.isNew=false;formData.newFileName=null;formData.newFileSize=null;}else if (formData.deleteInput){const isChecked=formData.deleteInput.checked;formData.deleteInput.checked=!isChecked;}this.render();}render(){this.listContainer.innerHTML='';let hasAttachments=false;this.formsData.forEach((formData,index)=>{const hasFile=formData.existingUrl||(formData.fileInput.files&&formData.fileInput.files.length>0);if (!hasFile){return;}hasAttachments=true;const ext=getFileExtension(formData.existingUrl||formData.newFileName||'');const size=formData.existingUrl?formData.existingSize:formData.newFileSize;const isDeleted=formData.deleteInput?formData.deleteInput.checked:false;const card=document.createElement('div');card.className=`attachment-card ${formData.isNew?'is-new':''}${isDeleted?'marked-for-deletion':''}`;card.innerHTML=`<div class="attachment-icon">${getIconForExtension(ext)}</div><div class="attachment-info"><input type="text" class="attachment-title-input"
value="${formData.titleInput.value}"
placeholder="عنوان الملف(مثال:دليل الرسوم)"
${isDeleted?'disabled':''}><div class="attachment-meta"><span class="attachment-badge">${ext}</span><span>${size||''}</span>${formData.isNew?'<span class="text-xs font-medium" style="color:var (--secondary-hover);">ملف جديد</span>':''}${isDeleted?'<span class="text-xs font-medium" style="color:var (--danger);">سيتم الحذف عند حفظ التغييرات</span>':''}</div></div><div class="attachment-actions">${formData.existingUrl?`<a href="${formData.existingUrl}" target="_blank" class="attachment-action-btn" title="تحميل أو معاينة"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px;"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"></path><polyline points="15 3 21 3 21 9"></polyline><line x1="10" y1="14" x2="21" y2="3"></line></svg></a>`:''}<button type="button" class="attachment-action-btn btn-danger" title="${isDeleted?'تراجع عن الحذف':'حذف الملف'}">${isDeleted?`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px;"><path d="M3 12h18M12 3v18"></path></svg>`:`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px;"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>`}</button></div>`;const cardTitleInput=card.querySelector('.attachment-title-input');cardTitleInput.addEventListener('input',(e)=>{formData.titleInput.value=e.target.value;});const deleteBtn=card.querySelector('.btn-danger');deleteBtn.addEventListener('click',()=>{this.toggleDelete(index);});this.listContainer.appendChild(card);});if (!hasAttachments){const emptyState=document.createElement('div');emptyState.className='text-center p-6 border rounded-lg';emptyState.style.borderColor='var (--border)';emptyState.style.backgroundColor='var (--surface-2)';emptyState.innerHTML=`<p class="text-sm mb-0" style="color:var (--text-muted);">${this.emptyText}</p>`;this.listContainer.appendChild(emptyState);}}}document.addEventListener('DOMContentLoaded',()=>{new UniversityAttachmentsManager();});})();